export type FailureKind = "declined" | "timeout"

export type PaymentData = {
  cardNumber: string
  expiry: string
  cvc: string
  /** Prototype control: fail with a network timeout instead of a card decline */
  simulateTimeout: boolean
  failure: FailureKind | null
}

export const PAYMENT_INITIAL: PaymentData = {
  cardNumber: "",
  expiry: "",
  cvc: "",
  simulateTimeout: false,
  failure: null,
}

export const PAYMENT_STEPS = ["payment", "failure"] as const

export const ORDER_TOTAL = "$84.50"

export type PaymentStepProps = {
  data: PaymentData
  patch: (p: Partial<PaymentData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}
