"use client"

import { FlowShell } from "../_shared/FlowShell"
import { useFlowState } from "../_shared/useFlowState"
import { PAYMENT_INITIAL, PAYMENT_STEPS, PaymentData } from "./schema"
import { Payment } from "./steps/Payment"
import { Failure } from "./steps/Failure"

export default function PaymentErrorPage() {
  const flow = useFlowState<PaymentData>({ totalSteps: PAYMENT_STEPS.length, initialData: PAYMENT_INITIAL })
  const props = { data: flow.data, patch: flow.patch, next: flow.next, back: flow.back, goTo: flow.goTo }
  const key = PAYMENT_STEPS[flow.step]
  return (
    <FlowShell
      title="Payment error"
      step={flow.step}
      totalSteps={PAYMENT_STEPS.length}
      onReset={flow.reset}
      phoneBackground="var(--atlas-background)"
    >
      {key === "payment" && <Payment {...props} />}
      {key === "failure" && <Failure {...props} />}
    </FlowShell>
  )
}
